package ec.edu.monster.vistas;
import ec.edu.monster.controladores.BancaControlador; import ec.edu.monster.modelos.Modelos.*; import java.math.BigDecimal; import java.util.*;
/** Vista de terminal: no contiene llamadas SOAP. */
public final class ConsolaVista {
 private final Scanner in=new Scanner(System.in); private final BancaControlador c=new BancaControlador();
 public void ejecutar(){cabecera();while(true){try{login();if(menu())return;}catch(Exception e){error(limpiar(e.getMessage()));}}}
 private void login()throws Exception{System.out.print("\n  Usuario: ");String u=in.nextLine();System.out.print("  Contraseña: ");String p=in.nextLine();Sesion s=c.iniciar(u,p);mensaje("Bienvenido/a, "+s.nombre()+".");}
 private boolean menu(){while(true){System.out.println("\n+------------------------ EUREKABANK -------------------------+\n|  1. Mis cuentas       2. Movimientos     3. Transferir      |\n|  4. Ingreso/retiro    5. Reversar        6. Mi perfil       |\n|  0. Salir                                                    |\n+--------------------------------------------------------------+");System.out.print("  Elige una opción: ");try{switch(in.nextLine().trim()){case "1"->cuentas();case "2"->movimientos();case "3"->transferir();case "4"->movimiento();case "5"->reversa();case "6"->perfil();case "0"->{mensaje("Sesión finalizada. Hasta pronto.");return true;}default->error("Opción no válida.");}}catch(Exception e){String detalle=limpiar(e.getMessage());error(detalle);if(esErrorSesion(detalle))return false;}}}
 private void cuentas()throws Exception{List<Cuenta> cs=c.cuentas();System.out.println("\n  CUENTAS DISPONIBLES");for(Cuenta x:cs)System.out.printf("  • %s  |  $ %,.2f  |  %s%n",x.numero(),x.saldo(),x.estado());}
 private void movimientos()throws Exception{System.out.print("  Número de cuenta: ");for(Movimiento x:c.movimientos(in.nextLine()))System.out.printf("  %s | %-18s | $ %,.2f | %s%n",x.id(),x.tipo(),x.monto(),x.fecha());}
 private void transferir()throws Exception{System.out.print("  Número de cuenta origen: ");String o=in.nextLine();System.out.print("  Número de cuenta destino: ");String d=in.nextLine();System.out.print("  Monto: ");mensaje(c.transferir(o,d,new BigDecimal(in.nextLine())).mensaje());}
 private void movimiento()throws Exception{System.out.print("  Tipo [INGRESO/RETIRO]: ");String t=in.nextLine().trim().toUpperCase();System.out.print("  Número de cuenta: ");String id=in.nextLine();System.out.print("  Monto: ");mensaje(c.registrar(t,id,new BigDecimal(in.nextLine())).mensaje());}
 private void reversa()throws Exception{System.out.print("  ID de transacción: ");mensaje(c.reversar(in.nextLine()).mensaje());}
 private void perfil()throws Exception{Perfil p=c.perfil();System.out.println("\n  PERFIL\n  "+p.nombre()+"\n  @"+p.usuario()+"  ·  "+p.telefono());}
 private void cabecera(){System.out.println("\n+--------------------------------------------------------------+\n|              E U R E K A B A N K                             |\n|                    BANCA DIGITAL                              |\n+--------------------------------------------------------------+");}
 private boolean esErrorSesion(String mensaje){String valor=mensaje.toLowerCase();return valor.contains("token inválido")||valor.contains("token invalido")||valor.contains("token expirado")||valor.contains("token revocado")||valor.contains("sesión expirada")||valor.contains("sesion expirada");}
 private void mensaje(String m){System.out.println("\n  [OK] "+m);}private void error(String m){System.out.println("\n  [ERROR] "+m);}private String limpiar(String s){return s==null?"Error de comunicación.":s.replaceAll("(?s)<[^>]*>","").trim();}
}
